const staffSubscriptionCounts = `-- name: StaffSubscriptionCounts :one
WITH subs AS (
    SELECT s.id, s.tenant_id, s.package_id, s.status, s.starts_at, s.trial_ends_at, s.expires_at, s.cancelled_at, s.cancellation_reason, s.overrides, s.created_at, s.updated_at, s.next_package_id, s.cancel_at_period_end, s.billing_cycle, s.next_billing_cycle FROM subscriptions s
    JOIN tenants t ON t.id = s.tenant_id AND t.deleted_at IS NULL
),
in_force AS (
    SELECT DISTINCT ON (tenant_id) id, tenant_id FROM subs
    WHERE (status IN ('active', 'trial') OR (status = 'scheduled' AND starts_at <= now()))
      AND expires_at > now()
    ORDER BY tenant_id, id DESC
),
lapsed AS (
    SELECT DISTINCT ON (tenant_id) id, tenant_id FROM subs
    WHERE status IN ('active', 'expired', 'past_due') AND expires_at <= now() AND expires_at > $1
      AND tenant_id NOT IN (SELECT tenant_id FROM in_force)
    ORDER BY tenant_id, expires_at DESC, id DESC
),
read_only AS (
    SELECT DISTINCT ON (tenant_id) id, tenant_id FROM subs
    WHERE status IN ('active', 'trial', 'expired', 'past_due', 'cancelled') AND starts_at <= now()
      AND tenant_id NOT IN (SELECT tenant_id FROM in_force)
      AND tenant_id NOT IN (SELECT tenant_id FROM lapsed)
    ORDER BY tenant_id, expires_at DESC NULLS LAST, id DESC
)
SELECT
    (SELECT count(*) FROM in_force f JOIN subs s ON s.id = f.id WHERE s.status <> 'trial') AS active,
    (SELECT count(*) FROM in_force f JOIN subs s ON s.id = f.id WHERE s.status = 'trial') AS trial,
    (SELECT count(*) FROM lapsed) AS grace,
    (SELECT count(*) FROM read_only) AS read_only,
    (SELECT count(*) FROM subs WHERE status = 'pending') AS pending,
    (SELECT count(*) FROM subs WHERE status = 'scheduled' AND starts_at > now()) AS scheduled,
    (SELECT count(*) FROM subs) AS all_rows
`

type StaffSubscriptionCountsRow struct {
	Active    int64 `json:"active"`
	Trial     int64 `json:"trial"`
	Grace     int64 `json:"grace"`
	ReadOnly  int64 `json:"read_only"`
	Pending   int64 `json:"pending"`
	Scheduled int64 `json:"scheduled"`
	AllRows   int64 `json:"all_rows"`
}

// A count per view of ListStaffSubscriptions (the tabs of the staff panel);
// the same standing rules.
func (q *Queries) StaffSubscriptionCounts(ctx context.Context, graceSince pgtype.Timestamptz) (StaffSubscriptionCountsRow, error) {
	row := q.db.QueryRow(ctx, staffSubscriptionCounts, graceSince)
	var i StaffSubscriptionCountsRow
	err := row.Scan(
		&i.Active,
		&i.Trial,
		&i.Grace,
		&i.ReadOnly,
		&i.Pending,
		&i.Scheduled,
		&i.AllRows,
	)
	return i, err
}

const subscriptionPaidValue = `-- name: SubscriptionPaidValue :one
SELECT COALESCE(sum(gross - refunded_amount), 0)::bigint AS paid
FROM payments
WHERE subscription_id = $1 AND status IN ('completed', 'refunded')
`

// What the organization paid for a subscription's period: the value bought
// (gross) less what was given back.
func (q *Queries) SubscriptionPaidValue(ctx context.Context, subscriptionID *int64) (int64, error) {
	row := q.db.QueryRow(ctx, subscriptionPaidValue, subscriptionID)
	var paid int64
	err := row.Scan(&paid)
	return paid, err
}

const suspendLapsedTenants = `-- name: SuspendLapsedTenants :many
UPDATE tenants t
SET is_active  = false,
    updated_at = now()
WHERE t.is_active
  AND t.deleted_at IS NULL
  AND t.id <> $1
  AND EXISTS (
    SELECT 1 FROM subscriptions s
    WHERE s.tenant_id = t.id AND s.status = 'expired' AND s.expires_at < $2
  )
  AND NOT EXISTS (
    SELECT 1 FROM subscriptions s
    WHERE s.tenant_id = t.id AND s.status IN ('active', 'trial', 'pending', 'scheduled', 'past_due')
  )
RETURNING t.id, t.name, t.code
`

type SuspendLapsedTenantsParams struct {
	KeepTenantID  int64              `json:"keep_tenant_id"`
	ExpiredBefore pgtype.Timestamptz `json:"expired_before"`
}

type SuspendLapsedTenantsRow struct {
	ID   int64  `json:"id"`
	Name string `json:"name"`
	Code string `json:"code"`
}

// Suspends active tenants whose subscription expired before @expired_before
// and that have nothing current or in progress (BILLING_SUSPEND_ON_EXPIRY).
func (q *Queries) SuspendLapsedTenants(ctx context.Context, arg SuspendLapsedTenantsParams) ([]SuspendLapsedTenantsRow, error) {
	rows, err := q.db.Query(ctx, suspendLapsedTenants, arg.KeepTenantID, arg.ExpiredBefore)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SuspendLapsedTenantsRow{}
	for rows.Next() {
		var i SuspendLapsedTenantsRow
		if err := rows.Scan(&i.ID, &i.Name, &i.Code); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const tenantHadSubscription = `-- name: TenantHadSubscription :one
SELECT EXISTS (
    SELECT 1 FROM subscriptions
    WHERE tenant_id = $1
      AND status IN ('active', 'trial', 'expired', 'past_due', 'cancelled')
      AND starts_at <= now()
)::bool AS had
`

// Whether the tenant ever had a plan that started: one that never did
// cannot lapse into read-only.
func (q *Queries) TenantHadSubscription(ctx context.Context, tenantID int64) (bool, error) {
	row := q.db.QueryRow(ctx, tenantHadSubscription, tenantID)
	var had bool
	err := row.Scan(&had)
	return had, err
}

const tenantUsage = `-- name: TenantUsage :one
SELECT
    (SELECT count(*) FROM users u WHERE u.tenant_id = $1::bigint AND u.deleted_at IS NULL)::bigint AS users,
    (SELECT count(*) FROM branches b WHERE b.tenant_id = $1::bigint AND b.deleted_at IS NULL)::bigint AS branches,
    (SELECT COALESCE(sum(f.size), 0) FROM files f WHERE f.tenant_id = $1::bigint)::bigint AS storage_bytes
`

type TenantUsageRow struct {
	Users        int64 `json:"users"`
	Branches     int64 `json:"branches"`
	StorageBytes int64 `json:"storage_bytes"`
}

// What a tenant uses of its plan's limits (users.max, branches.max,
// storage.mb): the same rows the limit checks count.
func (q *Queries) TenantUsage(ctx context.Context, tenantID int64) (TenantUsageRow, error) {
	row := q.db.QueryRow(ctx, tenantUsage, tenantID)
	var i TenantUsageRow
	err := row.Scan(&i.Users, &i.Branches, &i.StorageBytes)
	return i, err
}

