const updatePaymentGateway = `-- name: UpdatePaymentGateway :execrows
UPDATE payments
SET gateway_ref      = COALESCE($1::text, gateway_ref),
    gateway_status   = COALESCE($2::text, gateway_status),
    gateway_response = $3,
    updated_at       = now()
WHERE id = $4
`

type UpdatePaymentGatewayParams struct {
	GatewayRef      *string `json:"gateway_ref"`
	GatewayStatus   *string `json:"gateway_status"`
	GatewayResponse []byte  `json:"gateway_response"`
	ID              int64   `json:"id"`
}

func (q *Queries) UpdatePaymentGateway(ctx context.Context, arg UpdatePaymentGatewayParams) (int64, error) {
	result, err := q.db.Exec(ctx, updatePaymentGateway,
		arg.GatewayRef,
		arg.GatewayStatus,
		arg.GatewayResponse,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updatePaymentStatus = `-- name: UpdatePaymentStatus :one
UPDATE payments
SET status         = $1,
    paid_at        = CASE WHEN $1::text = 'completed' THEN COALESCE(paid_at, now()) ELSE paid_at END,
    recorded_by    = COALESCE($2, recorded_by),
    gateway_status = COALESCE($3::text, gateway_status),
    updated_at     = now()
WHERE id = $4
  AND (
      status = 'pending'
      OR status = $1::text
      OR (status = 'failed' AND $1::text = 'completed')
      OR (status = 'completed' AND $1::text = 'refunded')
  )
RETURNING id, tenant_id, subscription_id, payment_method, status, amount, currency, gateway_ref, gateway_status, gateway_response, invoice_number, paid_at, recorded_by, created_by, updated_by, created_at, updated_at, kind, lines, gross, balance_applied, replaces_subscription_id, refunded_amount
`

type UpdatePaymentStatusParams struct {
	Status        string  `json:"status"`
	RecordedBy    *int64  `json:"recorded_by"`
	GatewayStatus *string `json:"gateway_status"`
	ID            int64   `json:"id"`
}

// Allowed transitions only (M8): pending -> anything, failed -> completed (a
// late genuine success), completed -> refunded, or a no-op repeat.
func (q *Queries) UpdatePaymentStatus(ctx context.Context, arg UpdatePaymentStatusParams) (Payment, error) {
	row := q.db.QueryRow(ctx, updatePaymentStatus,
		arg.Status,
		arg.RecordedBy,
		arg.GatewayStatus,
		arg.ID,
	)
	var i Payment
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.SubscriptionID,
		&i.PaymentMethod,
		&i.Status,
		&i.Amount,
		&i.Currency,
		&i.GatewayRef,
		&i.GatewayStatus,
		&i.GatewayResponse,
		&i.InvoiceNumber,
		&i.PaidAt,
		&i.RecordedBy,
		&i.CreatedBy,
		&i.UpdatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Kind,
		&i.Lines,
		&i.Gross,
		&i.BalanceApplied,
		&i.ReplacesSubscriptionID,
		&i.RefundedAmount,
	)
	return i, err
}

